Input: {"question": "Which organization is Uee affiliated with?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "d1", "start": 0, "end": 7, "text": "**Uee**"}, "D1S2": {"document_number": 1, "doc_id": "d1", "start": 9, "end": 108, "text": "Uee (Hangul: 유이) is a South Korean singer and actress born on April 9, 1989, in Daegu, South Korea."}, "D1S3": {"document_number": 1, "doc_id": "d1", "start": 109, "end": 231, "text": "She is best known as a member of the South Korean girl group After School and has also pursued a successful acting career."}, "D1S4": {"document_number": 1, "doc_id": "d1", "start": 232, "end": 257, "text": "**Early Life and Career**"}, "D1S5": {"document_number": 1, "doc_id": "d1", "start": 259, "end": 305, "text": "Uee was born Kim Yu-jin in Daegu, South Korea."}, "D1S6": {"document_number": 1, "doc_id": "d1", "start": 306, "end": 418, "text": "She debuted as a member of After School in 2009 and has since released several successful albums with the group."}, "D1S7": {"document_number": 1, "doc_id": "d1", "start": 419, "end": 578, "text": "In addition to her music career, Uee has also acted in various television dramas and films, including \"Queen Seondeok\", \"Ojakgyo Family\", and \"Golden Rainbow\"."}, "D1S8": {"document_number": 1, "doc_id": "d1", "start": 579, "end": 618, "text": "**Affiliation with Good Entertainment**"}, "D1S9": {"document_number": 1, "doc_id": "d1", "start": 620, "end": 721, "text": "Uee is currently affiliated with Good Entertainment, a South Korean entertainment management company."}, "D1S10": {"document_number": 1, "doc_id": "d1", "start": 722, "end": 946, "text": "According to various sources, including news articles and industry reports, Uee signed an exclusive contract with Good Entertainment in 2017, following her departure from Pledis Entertainment, her previous management agency."}, "D1S11": {"document_number": 1, "doc_id": "d1", "start": 947, "end": 953, "text": "[1][2]"}, "D1S12": {"document_number": 1, "doc_id": "d1", "start": 955, "end": 1125, "text": "Good Entertainment, founded in 2000, is a leading entertainment management company in South Korea, representing a range of artists, including actors, singers, and models."}, "D1S13": {"document_number": 1, "doc_id": "d1", "start": 1126, "end": 1281, "text": "The company has a reputation for nurturing talented artists and providing them with opportunities for growth and development in the entertainment industry."}, "D1S14": {"document_number": 1, "doc_id": "d1", "start": 1282, "end": 1296, "text": "**References**"}, "D1S15": {"document_number": 1, "doc_id": "d1", "start": 1298, "end": 1350, "text": "[1] \"Uee signs with Good Entertainment\" (in Korean)."}, "D1S16": {"document_number": 1, "doc_id": "d1", "start": 1351, "end": 1358, "text": "Newsen."}, "D1S17": {"document_number": 1, "doc_id": "d1", "start": 1359, "end": 1370, "text": "2017-05-15."}, "D1S18": {"document_number": 1, "doc_id": "d1", "start": 1371, "end": 1392, "text": "Retrieved 2022-02-20."}, "D1S19": {"document_number": 1, "doc_id": "d1", "start": 1393, "end": 1460, "text": "[2] \"Uee joins Good Entertainment, starts new chapter\" (in Korean)."}, "D1S20": {"document_number": 1, "doc_id": "d1", "start": 1461, "end": 1466, "text": "Osen."}, "D1S21": {"document_number": 1, "doc_id": "d1", "start": 1467, "end": 1478, "text": "2017-05-16."}, "D1S22": {"document_number": 1, "doc_id": "d1", "start": 1479, "end": 1500, "text": "Retrieved 2022-02-20."}, "D2S1": {"document_number": 2, "doc_id": "d2", "start": 0, "end": 54, "text": "**Uee's Affiliation with the Smithsonian Institution**"}, "D2S2": {"document_number": 2, "doc_id": "d2", "start": 56, "end": 256, "text": "Uee, a renowned South Korean singer and actress, has been affiliated with the prestigious Smithsonian Institution, a group of museums and research centers administered by the United States government."}, "D2S3": {"document_number": 2, "doc_id": "d2", "start": 257, "end": 417, "text": "This affiliation has been a subject of interest among fans and scholars alike, with several studies and events shedding light on the nature of this partnership."}, "D2S4": {"document_number": 2, "doc_id": "d2", "start": 418, "end": 438, "text": "**Early Beginnings**"}, "D2S5": {"document_number": 2, "doc_id": "d2", "start": 440, "end": 618, "text": "The seeds of Uee's affiliation with the Smithsonian Institution were sown in 2010, when she participated in a cultural exchange program between South Korea and the United States."}, "D2S6": {"document_number": 2, "doc_id": "d2", "start": 619, "end": 802, "text": "During this program, Uee engaged in a series of workshops and lectures at the Smithsonian's National Museum of Natural History, where she explored the intersection of art and science."}, "D2S7": {"document_number": 2, "doc_id": "d2", "start": 803, "end": 829, "text": "**Collaborative Research**"}, "D2S8": {"document_number": 2, "doc_id": "d2", "start": 831, "end": 865, "text": "In 2012, Uee collaborated with Dr."}, "D2S9": {"document_number": 2, "doc_id": "d2", "start": 866, "end": 1045, "text": "Sophia Patel, a renowned anthropologist at the Smithsonian's National Museum of Natural History, on a research project examining the role of K-pop in promoting cultural diplomacy."}, "D2S10": {"document_number": 2, "doc_id": "d2", "start": 1046, "end": 1239, "text": "The study, titled \"K-Pop as Cultural Ambassador: A Case Study of Uee's Impact on International Relations,\" was published in the Journal of Cultural Anthropology and received widespread acclaim."}, "D2S11": {"document_number": 2, "doc_id": "d2", "start": 1240, "end": 1267, "text": "**Performances and Events**"}, "D2S12": {"document_number": 2, "doc_id": "d2", "start": 1269, "end": 1462, "text": "Uee has performed at several high-profile events hosted by the Smithsonian Institution, including the 2015 Smithsonian Folklife Festival, where she showcased traditional Korean music and dance."}, "D2S13": {"document_number": 2, "doc_id": "d2", "start": 1463, "end": 1638, "text": "In 2018, she participated in a special concert at the National Museum of American History, celebrating the 50th anniversary of the Smithsonian's Asian Pacific American Center."}, "D2S14": {"document_number": 2, "doc_id": "d2", "start": 1639, "end": 1670, "text": "**Exhibitions and Collections**"}, "D2S15": {"document_number": 2, "doc_id": "d2", "start": 1672, "end": 1810, "text": "The Smithsonian Institution has also recognized Uee's contributions to the world of music and art by featuring her in several exhibitions."}, "D2S16": {"document_number": 2, "doc_id": "d2", "start": 1811, "end": 2002, "text": "In 2019, the National Museum of Asian Pacific American History and Culture launched an exhibit titled \"K-Pop: A Global Phenomenon,\" which included artifacts and memorabilia from Uee's career."}, "D2S17": {"document_number": 2, "doc_id": "d2", "start": 2003, "end": 2222, "text": "Additionally, the Smithsonian's National Museum of American History has acquired several items from Uee's personal collection, including costumes and stage props, which are now part of the museum's permanent collection."}, "D2S18": {"document_number": 2, "doc_id": "d2", "start": 2223, "end": 2237, "text": "**References**"}, "D2S19": {"document_number": 2, "doc_id": "d2", "start": 2239, "end": 2250, "text": "* Patel, S."}, "D2S20": {"document_number": 2, "doc_id": "d2", "start": 2251, "end": 2258, "text": "(2012)."}, "D2S21": {"document_number": 2, "doc_id": "d2", "start": 2259, "end": 2345, "text": "K-Pop as Cultural Ambassador: A Case Study of Uee's Impact on International Relations."}, "D2S22": {"document_number": 2, "doc_id": "d2", "start": 2346, "end": 2395, "text": "Journal of Cultural Anthropology, 27(3), 345-362."}, "D2S23": {"document_number": 2, "doc_id": "d2", "start": 2396, "end": 2422, "text": "* Smithsonian Institution."}, "D2S24": {"document_number": 2, "doc_id": "d2", "start": 2423, "end": 2430, "text": "(2015)."}, "D2S25": {"document_number": 2, "doc_id": "d2", "start": 2431, "end": 2469, "text": "Smithsonian Folklife Festival Program."}}, "candidates": [{"candidate_id": "C0", "answer": "Good Entertainment", "card_ids": ["d1:c0"]}, {"candidate_id": "C1", "answer": "Smithsonian Institution", "card_ids": ["d2:c0"]}], "original_cards": [{"doc_id": "d1", "card_id": "d1:c0", "entity": "Uee", "scope": "Affiliation", "claim": "Uee is currently affiliated with Good Entertainment, a South Korean entertainment management company.", "answer": "Good Entertainment", "quote": "Uee is currently affiliated with Good Entertainment, a South Korean entertainment management company.", "original_document_number": 1}, {"doc_id": "d2", "card_id": "d2:c0", "entity": "Uee", "scope": "Affiliation", "claim": "Uee, a renowned South Korean singer and actress, has been affiliated with the prestigious Smithsonian Institution.", "answer": "Smithsonian Institution", "quote": "Uee, a renowned South Korean singer and actress, has been affiliated with the prestigious Smithsonian Institution, a group of museums and research centers administered by the United States government.", "original_document_number": 2}], "initial_answers": ["Good Entertainment", "Smithsonian Institution"]}
